class Task:
    def __init__(self, C, T, D, pi, gamma):
        self.C = C
        self.T = T
        self.D = D
        self.pi = pi
        self.gamma = gamma
        self.R = 0 # Worst-case response time, to be calculated

def is_task_schedulable(task_i):
    return task_i.R <= task_i.D

def is_system_schedulable(task_set):
    for task_i in task_set:
        if not is_task_schedulable(task_i):
            return False
    return True

def calculate_blocking_time(task_i, task_set):
    B_tau_i = 0
    for task_j in task_set:
        # Check if task_j is a lower priority task
        if task_j.pi < task_i.pi:
            # Check if task_j's threshold is high enough to block task_i
            if task_j.gamma >= task_i.pi:
                B_tau_i = max(B_tau_i, task_j.C)
    return B_tau_i

import math

def calculate_start_time(task_i, q, B_tau_i, task_set):
    S_i_q_current = B_tau_i + (q - 1) * task_i.C
    while True:
        S_i_q_next = B_tau_i + (q - 1) * task_i.C
        for task_k in task_set:
            if task_k.pi > task_i.pi: # Higher priority tasks
                S_i_q_next += math.ceil(S_i_q_current / task_k.T) * task_k.C

        if S_i_q_next == S_i_q_current:
            return S_i_q_current
        S_i_q_current = S_i_q_next

import math

def calculate_finish_time(task_i, q, S_i_q, task_set):
    F_i_q_current = S_i_q + task_i.C
    while True:
        F_i_q_next = S_i_q + task_i.C
        for task_k in task_set:
            if task_k.pi > task_i.gamma: # Tasks that can preempt after tau_i starts
                F_i_q_next += math.ceil((F_i_q_current - S_i_q) / task_k.T) * task_k.C

        if F_i_q_next == F_i_q_current:
            return F_i_q_current
        F_i_q_current = F_i_q_next
